mapper.sql:
FROM chkList
     LEFT JOIN ics15_checklist_write ON ( ics15_checklist_id = ics10_checklist_id
                                      AND ics15_company_id   = #{companyId}
                                      AND ics15_person_id    = person_id
                                      AND ics15_cycle_type   = #{cycleType}
                                      AND ics15_check_yyyymm = TO_CHAR(#{stdDate}::date,'YYYY.MM') )


AND ics21_checklist_l_class_id = #{checklistLClassId}


AND ics23_checklist_m_class_id = #{checklistMClassId}

AND COALESCE(ics15_confirmer_id, confirmer_id) = #{confirmerId}

AND COALESCE(ics15_fix_yn,'false') = 'false'


AND COALESCE(ics15_confirm_yn,'false') = 'false'

AND CONCAT(ics10_check_l_class_nm, ics10_check_m_class_nm, ics10_content, org_nm, person_nm) ILIKE #{searchText}

mapper.select:
SELECT ics10_checklist_id AS checklist_id , ics11_company_id AS company_id , ics10_content AS content , ics10_criterion AS criterion , ics10_seq AS seq , ics10_checklist_m_class_id AS checklist_m_class_id , ics21_checklist_l_class_id AS check_l_class_id , ics10_check_l_class_nm AS check_l_class_name , ics10_check_m_class_nm AS check_m_class_name , ics15_checklist_write_id AS checklist_write_id , CASE WHEN ics15_answer_cd IS NOT NULL THEN f_cdnm('AnswerCode', ics15_answer_cd, ics11_company_id, #{stdDate}) ELSE '' END ||CASE WHEN ics15_reason IS NOT NULL THEN ' ('||ics15_reason||')' ELSE '' END AS reason , org_nm AS org_name , person_id AS person_id , person_nm AS person_name , COALESCE(ics15_fix_yn,'false') = 'true' AS fix_yn , COALESCE(ics15_confirm_yn,'false') = 'true' AS confirm_yn
WHERE 1=1
ORDER BY ics10_check_l_class_seq, ics10_check_m_class_seq, ics10_seq, ics10_content, org_nm, person_nm LIMIT #{limit} OFFSET #{offset}

SELECT ics15_checklist_write_id
  FROM ics15_checklist_write
 WHERE ics15_company_id   = #{companyId}
   AND ics15_checklist_id = #{checklistId}
   AND ics15_person_id    = #{personId}
   AND ics15_check_yyyymm = #{yyyymm}
   AND ics15_cycle_type   = #{cycleType}
 ORDER BY ics15_checklist_write_id
 LIMIT 1

mapper.update:
UPDATE ics15_checklist_write
   SET ics15_confirm_yn       = #{confirmYn}
     , ics15_confirmer_id     = #{confirmerId}
     , ics15_confirm_datetime = f_sysdate()
 WHERE ics15_checklist_write_id = #{checklistWriteId}
   AND ics15_company_id         = #{companyId}
